package org.humanjourney.core.juice;
import com.google.gson.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class JuiceV2DefinitionTest {
 private final JuiceDefinition.References refs=new JuiceDefinition.References(){public boolean bottleSupported(String id){return id.equals("fixture:source");}public Set<String> ingredient(String item,String tag){return item!=null&&item.equals("fixture:material")?Set.of(item):Set.of();}};
 JsonObject nativeData(){return JsonParser.parseString("{\"schema_version\":2,\"id\":\"synthetic\",\"ingredient\":{\"item\":\"fixture:material\"},\"bottle_ingredient_count\":2,\"canteen_ingredient_count\":8,\"bottle\":{\"type\":\"native\",\"item\":\"fixture:source\"},\"canteen_display_name\":\"Fixture Canteen\",\"heal_per_drink\":1}").getAsJsonObject();}
 JsonObject custom(){var o=nativeData();o.add("bottle",JsonParser.parseString("{\"type\":\"custom\",\"display_name\":\"Fixture Bottle\",\"effect_source_item\":\"fixture:source\"}"));return o;}
 JuiceDefinition parse(JsonObject o){return JuiceDefinition.parse(o,refs);}
 @Test void versionOneKeepsNativeAndOneOneDefaults(){var o=nativeData();o.addProperty("schema_version",1);o.remove("bottle");o.remove("bottle_ingredient_count");o.remove("canteen_ingredient_count");o.addProperty("bottle_item","fixture:source");var d=parse(o);assertEquals(1,d.schemaVersion());assertEquals(1,d.bottleIngredientCount());assertEquals(1,d.canteenIngredientCount());assertFalse(d.bottle().custom());assertEquals("fixture:source",d.bottleItem());}
 @Test void nativeV2LoadsIndependentCounts(){var d=parse(nativeData());assertEquals(2,d.schemaVersion());assertEquals(2,d.bottleIngredientCount());assertEquals(8,d.canteenIngredientCount());assertEquals("fixture:source",d.effectSourceItem());}
 @Test void customV2LoadsSharedCarrierAndNativeSource(){var d=parse(custom());assertTrue(d.bottle().custom());assertEquals("human_journey_core:juice_bottle",d.bottleItem());assertEquals("Fixture Bottle",d.bottle().displayName());assertEquals("fixture:source",d.effectSourceItem());}
 @Test void quantityLimitsAndIntegersAreStrict(){for(String key:List.of("bottle_ingredient_count","canteen_ingredient_count"))for(double n:new double[]{0,-1,65,1.5,Double.POSITIVE_INFINITY,Double.NaN}){var o=nativeData();o.addProperty(key,n);assertThrows(IllegalArgumentException.class,()->parse(o));}}
 @Test void missingAndStringQuantitiesRejected(){for(String key:List.of("bottle_ingredient_count","canteen_ingredient_count")){var o=nativeData();o.remove(key);assertThrows(IllegalArgumentException.class,()->parse(o));var s=nativeData();s.addProperty(key,"2");assertThrows(IllegalArgumentException.class,()->parse(s));}}
 @Test void boundaryAndApprovedRangePairsAreRepresentableWithoutCatalog(){for(int[] pair:new int[][]{{1,1},{1,3},{2,5},{2,8},{64,64}}){var o=nativeData();o.addProperty("bottle_ingredient_count",pair[0]);o.addProperty("canteen_ingredient_count",pair[1]);var d=parse(o);assertEquals(pair[0],d.bottleIngredientCount());assertEquals(pair[1],d.canteenIngredientCount());}}
 @Test void missingOrUnsupportedBottleModeRejected(){for(String b:List.of("null","{}","{\"type\":\"other\"}")){var o=nativeData();o.add("bottle",JsonParser.parseString(b));assertThrows(IllegalArgumentException.class,()->parse(o));}}
 @Test void invalidNativeBottleAndCustomSourceRejected(){var o=nativeData();o.getAsJsonObject("bottle").addProperty("item","fixture:missing");assertThrows(IllegalArgumentException.class,()->parse(o));var c=custom();c.getAsJsonObject("bottle").addProperty("effect_source_item","fixture:missing");assertThrows(IllegalArgumentException.class,()->parse(c));}
 @Test void customNameAndModeSpecificFieldsValidated(){for(String name:new String[]{""," ","Bad\nName"}){var o=custom();o.getAsJsonObject("bottle").addProperty("display_name",name);assertThrows(IllegalArgumentException.class,()->parse(o));}var o=custom();o.getAsJsonObject("bottle").addProperty("item","fixture:source");assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void severalCustomDefinitionsMayShareEffectSourceButNotIngredient(){var a=parse(custom());var b=new JuiceDefinition(2,"other",a.bottle(),new JuiceDefinition.Ingredient("fixture:other",null,Set.of("fixture:other")),2,8,"Other",1);var c=JuiceCatalog.of(List.of(a,b));assertEquals(2,c.definitions().size());assertTrue(c.bottles().isEmpty());assertThrows(IllegalArgumentException.class,()->JuiceCatalog.of(List.of(a,new JuiceDefinition(2,"bad",a.bottle(),a.ingredient(),2,8,"Bad",1))));}
}
